// Builds the MCP tool reference pages from the inventory generated by the
// Yorishiro server tests (docs/en/mcp-tools.md in yorishiro-ai/yorishiro).
//
//   node scripts/generate-mcp-reference.mjs [path-or-url-to-inventory.md]
import { readFile, writeFile } from "node:fs/promises";

const DEFAULT_SOURCE =
  "https://raw.githubusercontent.com/yorishiro-ai/yorishiro/develop/docs/en/mcp-tools.md";
const source = process.argv.slice(2).find((a) => a !== "--") ?? DEFAULT_SOURCE;
const text = /^https?:/.test(source)
  ? await (await fetch(source)).text()
  : await readFile(source, "utf8");

const SCOPE_RE = /\s*\(requires (\w+) scope(?:, [^)]*)?\)\.?/;

function typeLabel(p) {
  const base = Array.isArray(p.type)
    ? p.type.filter((t) => t !== "null").join(" or ")
    : (p.type ?? "any");
  const nullable = Array.isArray(p.type) && p.type.includes("null") ? " or null" : "";
  return `${base}${p.format ? ` (${p.format})` : ""}${nullable}`;
}

function parseTools(section) {
  const tools = [];
  for (const m of section.matchAll(
    /### `(\w+)`\n\n([\s\S]*?)\n\nInput schema:\n\n```json\n([\s\S]*?)\n```/g,
  )) {
    const [, name, rawDescription, schemaJson] = m;
    const schema = JSON.parse(schemaJson);
    const scope = rawDescription.match(SCOPE_RE)?.[1];
    if (!scope) throw new Error(`No scope found in description of ${name}`);
    const description = rawDescription
      .replace(SCOPE_RE, (m, _s, offset, whole) => {
        if (/[.。]$/.test(whole.slice(0, offset))) return "";
        return whole.slice(offset + m.length).trim() ? "." : "";
      })
      .replace(/\s*\n\s*/g, " ")
      .trim()
      .replace(/([^.。])$/, "$1.");
    const required = new Set(schema.required ?? []);
    const params = Object.entries(schema.properties ?? {}).map(([key, p]) => ({
      name: key,
      type: typeLabel(p),
      required: required.has(key),
      description: (p.description ?? "").replace(/\s*\n\s*/g, " ").trim(),
    }));
    tools.push({ name, scope, description, params });
  }
  return tools;
}

const [, communityPart, enterprisePart] = text.match(
  /## Community tools([\s\S]*?)## Enterprise-only tools([\s\S]*?)<!-- END GENERATED MCP INVENTORY -->/,
);
const community = parseTools(communityPart);
const enterprise = parseTools(enterprisePart);

const cell = (s) => s.replace(/\|/g, "\\|");

const labels = {
  en: {
    title: "MCP Tools",
    description: "Tools that Yorishiro exposes to MCP clients.",
    intro: `Yorishiro serves the Model Context Protocol over Streamable HTTP at \`/mcp\`. Send your API key in the \`Authorization: Bearer <api-key>\` header.

Every tool needs an API key with a minimum scope. Scopes are cumulative: \`read\` < \`write\` < \`schema\` < \`migration\`. A key with a higher scope can call every tool that needs a lower one. A call without enough scope returns a tool error, not a protocol error.

If your clients reach the server through a hostname other than \`localhost\`, add that hostname to \`YORISHIRO_MCP_ALLOWED_HOSTS\` (comma-separated). See [Configuration](../../configuration/).

Your MCP client lists the tools your server actually offers. This page lists the tools in the current release.`,
    tools: "Tools",
    overview: ["Tool", "Edition", "Scope", "Purpose"],
    community: "Community tools",
    editions: ["Community", "Enterprise"],
    enterprise: "Enterprise tools",
    enterpriseNote: "These tools are available in the Enterprise edition only.",
    params: ["Parameter", "Type", "Required", "Description"],
    yes: "Yes",
    no: "No",
    scope: "Required scope",
    noParams: "This tool takes no parameters.",
    note: "",
  },
  ja: {
    title: "MCPツール",
    description: "YorishiroがMCPクライアントに公開するツールの一覧です。",
    intro: `Yorishiroは、Model Context ProtocolをStreamable HTTPで \`/mcp\` に公開します。APIキーは \`Authorization: Bearer <api-key>\` ヘッダーで送ります。

どのツールにも、呼び出しに必要な最小のスコープがあります。スコープは \`read\`、\`write\`、\`schema\`、\`migration\` の順に高くなり、高いスコープのキーは低いスコープのツールもすべて呼び出せます。スコープが足りない呼び出しは、プロトコルエラーではなくツールのエラーとして返ります。

\`localhost\` 以外のホスト名でサーバーにアクセスするクライアントがある場合は、そのホスト名を \`YORISHIRO_MCP_ALLOWED_HOSTS\` にカンマ区切りで追加します。詳しくは[設定](../../configuration/)を参照してください。

実際に使えるツールは、MCPクライアントが一覧で取得できます。このページには現在のリリースのツールを載せています。

ツールとパラメーターの説明は、サーバーが返す英語のまま掲載しています。`,
    tools: "ツール",
    overview: ["ツール", "エディション", "スコープ", "用途"],
    community: "Communityのツール",
    editions: ["Community", "Enterprise"],
    enterprise: "Enterpriseのツール",
    enterpriseNote: "これらのツールはEnterprise版でのみ使えます。",
    params: ["パラメーター", "型", "必須", "説明"],
    yes: "はい",
    no: "いいえ",
    scope: "必要なスコープ",
    noParams: "このツールにパラメーターはありません。",
    note: "",
  },
};

function render(l) {
  const out = [];
  out.push("---", `title: "${l.title}"`, `description: "${l.description}"`, "---", "");
  out.push("{/* Generated by scripts/generate-mcp-reference.mjs. Do not edit by hand. */}", "");
  out.push(l.intro, "");
  out.push(`## ${l.tools}`, "");
  out.push(`| ${l.overview.join(" | ")} |`, "| --- | --- | --- | --- |");
  for (const [i, tools] of [community, enterprise].entries())
    for (const t of tools)
      out.push(
        `| [\`${t.name}\`](#${t.name}) | ${l.editions[i]} | \`${t.scope}\` | ${cell(t.description.split(/(?<=\.)\s/)[0])} |`,
      );
  out.push("");
  const section = (heading, note, tools) => {
    out.push(`## ${heading}`, "");
    if (note) out.push(note, "");
    for (const t of tools) {
      out.push(`### ${t.name}`, "", t.description, "", `${l.scope}: \`${t.scope}\``, "");
      if (t.params.length === 0) {
        out.push(l.noParams, "");
        continue;
      }
      out.push(`| ${l.params.join(" | ")} |`, "| --- | --- | --- | --- |");
      for (const p of t.params)
        out.push(
          `| \`${p.name}\` | ${cell(p.type)} | ${p.required ? l.yes : l.no} | ${cell(p.description)} |`,
        );
      out.push("");
    }
  };
  section(l.community, "", community);
  section(l.enterprise, l.enterpriseNote, enterprise);
  return out.join("\n");
}

await writeFile("src/content/docs/reference/mcp-tools.mdx", render(labels.en));
await writeFile("src/content/docs/ja/reference/mcp-tools.mdx", render(labels.ja));
console.log(`Generated ${community.length} community and ${enterprise.length} enterprise tools.`);
